#include <iostream>

class Buf {
    int* data_;
    int n_;
public:
    Buf(int n) : data_(new int[n]), n_(n) {
        for (int i = 0; i < n_; ++i) data_[i] = i;
    }
    Buf(const Buf& o) : data_(new int[o.n_]), n_(o.n_) {   // 深拷贝：重新分配内存
        for (int i = 0; i < n_; ++i) data_[i] = o.data_[i];
        std::cout << "copy ";
    }
    ~Buf() { delete[] data_; }
    int sum() const {
        int s = 0;
        for (int i = 0; i < n_; ++i) s += data_[i];
        return s;
    }
};

int main() {
    Buf a(4);
    Buf b = a;              // 调用拷贝构造，深拷贝后二者独立
    std::cout << b.sum();
}
